import openpyxl, re
wb = openpyxl.load_workbook('init.xlsx')
ws = wb['Sheet1']

# Pattern vocabulary from the manually-highlighted sample rows (2-33)
vocab = set()
for r in range(2, 34):
    v = ws.cell(r, 56).value
    if v:
        for t in re.split(r'[ ,]+', v.strip()):
            if t:
                vocab.add(t)

def find_patterns(text):
    if not text:
        return ''
    toks = re.split(r'[ ,]+', text.strip())
    found = [t for t in toks if t in vocab]
    return ', '.join(found)

for r in range(2, 309):
    v = ws.cell(r, 56).value
    ws.cell(r, 56).value = find_patterns(v)

wb.save('output.xlsx')
print('done')
EOF
